const SCREEN_NAMES={executivo:'Painel Executivo COEVO',alertas:'Alertas & Pendências',juridico:'Painel Executivo Jurídico',ti:'Painel Executivo TI',engenharia:'Painel Executivo Engenharia / Obras',estrategia:'Estratégia & Metas',projetos:'Projetos',orcamento:'Orçamento',indicadores:'Indicadores & Relatórios',comites:'Comitês & Reuniões',ia:'IA & Inteligência',temis:'Têmis',ivo:'Ivo',auditoria:'Auditoria & Compliance',riscos:'Riscos',inconsistencias:'Central de Inconsistências',integracoes:'Integrações',agenda:'Agenda',calculadora:'Calculadora',documentos:'Documentos',lixeira:'Lixeira',usuarios:'Usuários & Permissões',configuracoes:'Configurações',backup:'Backup & Restauração',logs:'Logs / Auditoria'};
const CORPORATE_MENU=[
  {label:'INÍCIO',items:[['executivo','⌂','Painel Executivo COEVO'],['alertas','◌','Alertas & Pendências']]},
  {label:'GESTÃO',items:[['estrategia','◎','Estratégia & Metas'],['projetos','□','Projetos'],['orcamento','◇','Orçamento'],['indicadores','▥','Indicadores & Relatórios'],['comites','◈','Comitês & Reuniões']]},
  {label:'INTELIGÊNCIA',items:[['ia','✦','IA & Inteligência'],['temis','⚖','Têmis'],['ivo','▤','Ivo']]},
  {label:'GOVERNANÇA',items:[['auditoria','◉','Auditoria & Compliance'],['riscos','△','Riscos'],['inconsistencias','↻','Central de Inconsistências'],['integracoes','⌁','Integrações']]},
  {label:'UTILITÁRIOS',items:[['agenda','◷','Agenda'],['calculadora','＋','Calculadora'],['documentos','▧','Documentos'],['lixeira','⌫','Lixeira']]},
  {label:'ADMINISTRAÇÃO',admin:true,items:[['usuarios','○','Usuários & Permissões'],['configuracoes','⚙','Configurações'],['backup','↻','Backup & Restauração'],['logs','▤','Logs / Auditoria']]}
];
const DEPARTMENT_MODULES={
  'Jurídico':[['juridico','Painel Executivo Jurídico'],['comite','Comitê Jurídico'],['processos','Processos'],['contratos','Contratos'],['notificacoes','Notificações'],['recuperacao','Recuperação de Crédito'],['honorarios','Honorários Extrajudiciais'],['honorarios-judiciais','Honorários Judiciais'],['distratos','Distratos'],['retomadas','Retomadas'],['compra-venda','Recompras / Compra e venda'],['transferencia-intermediaria','Transferências'],['fatos','Prazos'],['riscos-regulatorio','Riscos e Regulatório']],
  'TI':[['ti','Painel Executivo TI'],['ti-projetos','Projetos'],['ti-chamados','Chamados'],['ti-sistemas','Sistemas'],['ti-inventario','Inventário'],['ti-licencas','Licenças'],['ti-aquisicoes','Aquisições'],['ti-infraestrutura','Infraestrutura'],['ti-seguranca','Segurança'],['ti-governanca','Governança de TI'],['ti-ia','IA & Automações'],['ti-fornecedores','Fornecedores']],
  'Engenharia / Obras':[['engenharia','Painel Executivo Engenharia / Obras']]
};
const SCREEN_PERMISSION={executivo:'central',alertas:'central',estrategia:'estrategia',projetos:'projetos',orcamento:'orcamento',indicadores:'central',comites:'comites',ia:'central',temis:'juridico',ivo:'juridico',auditoria:'*',riscos:'central',inconsistencias:'*',integracoes:'*',agenda:'agenda',calculadora:'agenda',documentos:'central',lixeira:'*',usuarios:'*',configuracoes:'*',backup:'*',logs:'*'};
const initialProjectId=new URLSearchParams(location.search).get('project');
const state={authenticated:false,screen:initialProjectId?'projetos':'executivo',legalModule:null,legalPreset:null,committeeDepartment:null,budgetDepartment:'Todos',dashboard:null,dashboardCatalog:null,configuredDashboard:null,dashboardPreference:null,dashboardPersonalizing:false,projects:null,projectDetail:null,selectedProjectId:initialProjectId,legalData:{},me:null,mondaySchedule:null,processFilters:{search:'',status:[],enterprise:[],responsible:[],scope:[],year:[],type:[],month:[],party:[]},processView:{advanced:false,page:1,pageSize:25,sort:'date',direction:'desc'},honorariumFilters:{search:'',status:[],enterprise:[],responsible:[],year:[],type:[],month:[],competence:[],paymentMethod:[],unit:[]},honorariumView:{advanced:false,page:1,pageSize:25,sort:'date',direction:'desc',summaryMode:'month'},legalDashboardFilters:{competence:currentCompetenceValue(),periodPreset:'portfolio',comparison:'none',comparisonCompetence:shiftCompetence(currentCompetenceValue(),-1),customCompetences:[],company:'COEVO',enterprise:'Todos',responsible:'Todos',processType:'Todos'},datePickerUi:{customOpen:false,mobileOpen:false,customYear:Number(currentCompetenceValue().slice(0,4)),draftCustomCompetences:[]},sidebarCollapsed:localStorage.getItem('patrono-sidebar-collapsed')==='true',mobileMenu:false,departmentsOpen:new Set(['Jurídico'])};
const app=document.getElementById('app');
document.addEventListener('keydown',event=>{if(event.key!=='Escape')return;if(state.datePickerUi.customOpen){event.preventDefault();cancelCustomPeriod();return}if(state.datePickerUi.mobileOpen){event.preventDefault();toggleMobileDateFilters(false);return}document.querySelectorAll('.competence-picker details[open]').forEach(details=>details.removeAttribute('open'))});
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const money=value=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(value||0);
const recordCount=value=>`<strong class="record-count-number">${Number(value||0).toLocaleString('pt-BR')}</strong>`;
const authHeaders=()=>window.__coevoToken?{Authorization:`Bearer ${window.__coevoToken}`}:{};
async function api(path,options={}){const response=await fetch(`/api${path}`,{...options,headers:{...authHeaders(),...(options.headers||{})}});const data=await response.json();if(!response.ok)throw new Error(data.error||'Não foi possível carregar os dados');return data}

function loginScreen(){return `<div class="login-page"><main class="login-card"><img class="login-logo" src="/assets/logo-coevo.png" alt="COEVO Construtora e Incorporadora"><h1 class="login-title">COEVO Alta Performance</h1><p class="login-slogan">Gestão, inteligência e decisão em uma só visão.</p><form onsubmit="submitLogin(event)"><label class="field-label" for="login-email">E-mail</label><input class="input" id="login-email" type="email" required><label class="field-label" for="login-password">Senha</label><div class="password-wrap"><input class="input" id="login-password" type="password" required><button class="eye" type="button" onclick="togglePassword()" aria-label="Mostrar ou ocultar senha">◉</button></div><button class="primary" style="width:100%;margin-top:20px" type="submit">Entrar na plataforma</button><button class="link-button" type="button" onclick="forgotPassword()">Esqueci minha senha</button><button class="link-button" type="button" onclick="showSignup()">Cadastre-se</button><div id="login-message"></div></form></main></div>`}
function mfaScreen(){return `<div class="login-page"><main class="login-card"><img class="login-logo" src="/assets/logo-coevo.png" alt="COEVO"><h1 class="login-title">Verificação de segurança</h1><p class="login-slogan">Digite o código MFA para continuar.</p><form onsubmit="submitMfa(event)"><label class="field-label" for="mfa-code">Código de autenticação</label><input class="input" id="mfa-code" inputmode="numeric" autocomplete="one-time-code" required><button class="primary" style="width:100%;margin-top:20px" type="submit">Validar acesso</button><button class="link-button" type="button" onclick="showLogin()">Voltar ao login</button><div id="mfa-message"></div></form></main></div>`}
function signupScreen(){return `<div class="login-page"><main class="login-card"><img class="login-logo" src="/assets/logo-coevo.png" alt="COEVO"><h1 class="login-title">Cadastre-se</h1><p class="login-slogan">O acesso será analisado por Cristiane Carneiro Rabelo.</p><form onsubmit="submitSignup(event)"><label class="field-label" for="signup-name">Nome completo</label><input class="input" id="signup-name" required><label class="field-label" for="signup-email">E-mail corporativo</label><input class="input" id="signup-email" type="email" required><label class="field-label" for="signup-department">Departamento</label><select class="input" id="signup-department"><option>Jurídico</option><option>Tecnologia</option></select><button class="primary" style="width:100%;margin-top:20px" type="submit">Enviar para aprovação</button><button class="link-button" type="button" onclick="showLogin()">Voltar ao login</button><div id="signup-message"></div></form></main></div>`}
function showLogin(){state.authenticated=false;app.innerHTML=loginScreen()}
function showSignup(){app.innerHTML=signupScreen()}
function togglePassword(){const input=document.getElementById('login-password');if(input)input.type=input.type==='password'?'text':'password'}
function forgotPassword(){document.getElementById('login-message').innerHTML='<div class="success">A solicitação de recuperação será encaminhada ao e-mail corporativo cadastrado.</div>'}
async function submitLogin(event){event.preventDefault();const message=document.getElementById('login-message');try{const result=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:document.getElementById('login-email').value,password:document.getElementById('login-password').value})}).then(async r=>({ok:r.ok,data:await r.json()}));if(!result.ok)throw new Error(result.data.error||'Credenciais inválidas');if(result.data.mfaRequired){window.__coevoChallenge=result.data.challenge;app.innerHTML=mfaScreen();return}if(!result.data.token)throw new Error('Não foi possível iniciar a sessão');window.__coevoToken=result.data.token;state.authenticated=true;await render()}catch(error){message.innerHTML=`<div class="error">${esc(error.message)}</div>`}}
async function submitMfa(event){event.preventDefault();const message=document.getElementById('mfa-message');try{const result=await fetch('/api/auth/mfa',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({challenge:window.__coevoChallenge,code:document.getElementById('mfa-code').value})}).then(async r=>({ok:r.ok,data:await r.json()}));if(!result.ok)throw new Error(result.data.error||'MFA inválido');window.__coevoToken=result.data.token;state.authenticated=true;await render()}catch(error){message.innerHTML=`<div class="error">${esc(error.message)}</div>`}}
async function submitSignup(event){event.preventDefault();const message=document.getElementById('signup-message');try{const data=await api('/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:document.getElementById('signup-name').value,email:document.getElementById('signup-email').value,department:document.getElementById('signup-department').value})});message.innerHTML=`<div class="success">${esc(data.message)}</div>`}catch(error){message.innerHTML=`<div class="error">${esc(error.message)}</div>`}}

function isAdmin(){return ['diretoria','administrador'].includes(state.me?.user?.role)}
function canSeeScreen(id){const modules=state.me?.permissions?.modules||[];const required=SCREEN_PERMISSION[id]||id;return modules.includes('*')||modules.includes(required)}
function menuButton(id,icon,label,extra=''){return `<button class="menu-item ${state.screen===id?'active':''}" onclick="go('${id}')" title="${esc(label)}" ${extra}><span class="menu-icon" aria-hidden="true">${icon}</span><span class="menu-text">${esc(label)}</span></button>`}
function toggleDepartment(name){state.departmentsOpen.has(name)?state.departmentsOpen.delete(name):state.departmentsOpen.add(name);render()}
function openDepartmentItem(department,id,label){SCREEN_NAMES[id]=label;if(department==='Jurídico'&&id!=='juridico'){state.screen='juridico';state.legalModule=id;if(id==='processos')syncProcessUrl();else if(id==='honorarios')syncHonorariumUrl();else if(id==='honorarios-judiciais')syncJudicialHonorariumUrl();else history.replaceState(null,'',location.pathname)}else{state.screen=id;state.legalModule=null;if(id==='juridico')syncLegalDashboardUrl();else history.replaceState(null,'',location.pathname)}state.mobileMenu=false;render()}
function departmentMenu(department){const display=department==='TI'?'Tecnologia':department;const icon=department==='Jurídico'?'⚖':department.startsWith('Engenharia')?'▱':'⌘';const open=state.departmentsOpen.has(department);const modules=DEPARTMENT_MODULES[department]||[];const active=department==='Jurídico'?state.screen==='juridico':department==='TI'?state.screen==='ti'||state.screen.startsWith('ti-'):state.screen==='engenharia';return `<div class="department-menu"><button class="menu-item department-toggle ${active?'active-parent':''}" onclick="toggleDepartment('${department}')" title="${esc(display)}"><span class="menu-icon">${icon}</span><span class="menu-text">${esc(display)}</span><span class="menu-arrow">${open?'⌄':'›'}</span></button><div class="submenu ${open?'open':''}">${modules.map(([id,label])=>`<button class="submenu-item ${(state.screen===id||(department==='Jurídico'&&state.legalModule===id))?'active':''}" onclick="openDepartmentItem('${department}','${id}','${esc(label)}')">${esc(label)}</button>`).join('')}</div></div>`}
function nav(){const departments=(state.dashboard?.departments||[]).filter(d=>!state.me?.user?.department||state.me.user.department===d.name||isAdmin());if(isAdmin()&&!departments.some(d=>d.name==='Engenharia / Obras'))departments.push({id:'dep-engenharia',name:'Engenharia / Obras'});const sections=CORPORATE_MENU.filter(s=>!s.admin||isAdmin()).map(s=>({...s,items:s.items.filter(i=>canSeeScreen(i[0]))})).filter(s=>s.items.length);const name=state.me?.user?.name||'Cristiane Rabelo';const role=state.me?.user?.role==='diretoria'?'Gestora':state.me?.user?.role||'Usuária';return `${state.mobileMenu?'<button class="drawer-overlay" onclick="toggleMobileMenu()" aria-label="Fechar menu"></button>':''}<aside class="side ${state.sidebarCollapsed?'collapsed':''} ${state.mobileMenu?'mobile-open':''}"><div class="side-head"><span class="brand" aria-label="COEVO Alta Performance"></span><button class="collapse-button" onclick="toggleSidebar()" title="Recolher ou expandir menu">${state.sidebarCollapsed?'›':'‹'}</button><button class="mobile-close" onclick="toggleMobileMenu()" aria-label="Fechar menu">×</button></div><nav class="nav" aria-label="Navegação principal">${sections.slice(0,1).map(s=>`<div class="nav-label">${s.label}</div>${s.items.map(i=>menuButton(...i)).join('')}`).join('')}<div class="nav-label">DEPARTAMENTOS</div>${departments.map(d=>departmentMenu(d.name)).join('')}${sections.slice(1).map(s=>`<div class="nav-label">${s.label}</div>${s.items.map(i=>menuButton(...i)).join('')}`).join('')}</nav><footer class="profile-area"><div class="profile-summary"><span class="avatar">${esc(name.charAt(0))}</span><span class="profile-text"><b>${esc(name.replace('Carneiro ','').replace('Cristiane ','Cristiane '))}</b><small>${esc(role)}</small></span></div><div class="profile-actions"><button onclick="go('perfil')" title="Meu Perfil">Perfil</button><button onclick="go('configuracoes')" title="Configurações">Config.</button><button onclick="logout()" title="Sair">Sair</button></div></footer></aside>`}
function shell(content){const top=state.screen==='juridico'?'':`<header class="top"><div><div class="eyebrow">Visão COEVO · Agosto 2026</div><div class="h1">${SCREEN_NAMES[state.screen]||'Módulo corporativo'}</div><div class="muted">Dados com origem, competência e trilha de auditoria.</div></div><div class="user">${esc(state.me?.user?.name||'Cristiane Rabelo')} · MFA ativo</div></header>`;return `<div class="shell">${nav()}<main class="main ${state.sidebarCollapsed?'collapsed':''}"><button class="mobile-menu-button" onclick="toggleMobileMenu()" aria-label="Abrir menu">☰</button><div class="mobile-brand">COEVO Alta Performance</div>${top}${content}</main></div>`}
function toggleSidebar(){state.sidebarCollapsed=!state.sidebarCollapsed;localStorage.setItem('patrono-sidebar-collapsed',String(state.sidebarCollapsed));render()}
function toggleMobileMenu(){state.mobileMenu=!state.mobileMenu;render()}
function logout(){window.__coevoToken=null;window.__coevoChallenge=null;state.authenticated=false;state.mobileMenu=false;showLogin()}
function go(screen){state.screen=screen;state.legalModule=null;state.mobileMenu=false;if(screen!=='projetos'){state.selectedProjectId=null;state.projectDetail=null}if(screen==='juridico')syncLegalDashboardUrl();else history.replaceState(null,'',screen==='projetos'&&state.selectedProjectId?`?project=${encodeURIComponent(state.selectedProjectId)}`:location.pathname);render()}
function financeRows(){return state.dashboard?.finance||state.dashboard?.departments?.map(d=>({departmentId:d.id,departmentName:d.name,budget:d.budget?.budgeted,planned:d.budget?.planned,committed:d.budget?.committed,actual:d.budget?.realized,balance:Number.isFinite(d.budget?.budgeted)&&Number.isFinite(d.budget?.committed)&&Number.isFinite(d.budget?.realized)?d.budget.budgeted-d.budget.committed-d.budget.realized:null,forecast:d.budget?.forecast,executionPercentage:d.budget?.budgeted?d.budget.realized/d.budget.budgeted:null,source:d.source||'Origem não informada'}))||[]}
function departmentFinance(name){return financeRows().find(item=>item.departmentName===name)||null}
function departmentBudget(name){const finance=departmentFinance(name);return finance?{budgeted:finance.budget,planned:finance.planned,committed:finance.committed,realized:finance.actual,forecast:finance.forecast}:{budgeted:null,planned:null,committed:null,realized:null,forecast:null}}
function goBudget(department='Todos'){state.budgetDepartment=department;state.screen='orcamento';state.legalModule=null;state.mobileMenu=false;render()}
function financeDisplay(value){return Number.isFinite(value)?money(value):'Dados ainda não disponíveis'}
function percentageDisplay(value){return Number.isFinite(value)?`${(value*100).toFixed(1)}%`:'Dados ainda não disponíveis'}

function departmentCentral(name){const department=state.dashboard.departments.find(d=>d.name===name);if(!department)return '';const b=departmentBudget(name);const events=state.dashboard.upcoming.filter(e=>e.department===name);return `<div class="section-title"><div><div class="eyebrow">Central Executiva · ${esc(name)}</div><h2>Visão da área</h2></div><span class="pill green">Visão departamental</span></div><div class="grid"><div class="card"><div class="muted">Realizado consolidado</div><div class="kpi">${financeDisplay(b.realized)}</div></div><div class="card"><div class="muted">Orçamento vigente</div><div class="kpi">${financeDisplay(b.budgeted)}</div></div><div class="card"><div class="muted">Planejado próximos meses</div><div class="kpi">${Number.isFinite(b.budgeted)&&Number.isFinite(b.realized)?money(Math.max(0,b.budgeted-b.realized)):'Dados ainda não disponíveis'}</div></div><div class="card"><div class="muted">Forecast</div><div class="kpi">${financeDisplay(b.forecast)}</div></div></div><div class="two section"><section class="card"><div class="section-title"><h2>Execução financeira</h2><b>${Number.isFinite(b.budgeted)&&b.budgeted>0&&Number.isFinite(b.realized)?(b.realized/b.budgeted*100).toFixed(1)+'%':'Dados ainda não disponíveis'}</b></div><div class="bar"><i style="width:${Math.min(100,b.budgeted?b.realized/b.budgeted*100:0)}%"></i></div><div class="row"><span>Planejado</span><b>${financeDisplay(b.planned)}</b></div><div class="row"><span>Realizado</span><b>${financeDisplay(b.realized)}</b></div><div class="row"><span>Saldo disponível</span><b>${Number.isFinite(b.budgeted)&&Number.isFinite(b.realized)&&Number.isFinite(b.committed)?money(b.budgeted-b.realized-b.committed):'Dados ainda não disponíveis'}</b></div></section><section class="card"><div class="section-title"><h2>Próximos compromissos</h2><span class="pill">${events.length}</span></div>${events.length?events.map(e=>`<div class="row"><div><b>${esc(e.title)}</b><div class="muted">${esc(e.date)} · ${esc(e.owner)}</div></div><span class="pill">${esc(e.status)}</span></div>`).join(''):'<div class="empty">Nenhum compromisso cadastrado.</div>'}</section></div>`}
function juridicoPage(){if(state.legalModule)return legalDetailPage();return legalDashboardPage()}
function openLegal(module){state.legalModule=module;render()}

function recordDate(row){const values=[row.createdAt,...Object.values(row.columns||{})];const match=values.map(v=>String(v||'').match(/\b(20\d{2})[-\/.](\d{2})[-\/.](\d{2})\b/)).find(Boolean);return match?`${match[1]}-${match[2]}-${match[3]}`:null}
function recordYear(row){return recordDate(row)?.slice(0,4)||'Não informado'}
function recordMonth(row){const d=recordDate(row);return d?new Intl.DateTimeFormat('pt-BR',{month:'long'}).format(new Date(`${d}T12:00:00`)):'Não informado'}
function recordEnterprise(row){return dashboardEnterprise(row)}
function processScope(row){const exact=String(row.columnsByTitle?.LOCAL||row.columns?.status3||'').toLowerCase();if(/\binterno/.test(exact))return 'Interno';if(/\bexterno/.test(exact))return 'Externo';return 'A classificar'}
function processStatus(row){const exact=String(row.columnsByTitle?.["'MEU TRABALHO'"]||row.columnsByTitle?.['STATUS (para comitê)']||row.columnsByTitle?.STATUS||row.columns?.status5||'').toLowerCase();if(/acordo/.test(exact))return 'Acordo';if(/finaliz|encerr|baix|extint|arquiv/.test(exact))return 'Finalizado';if(/acompanha/.test(exact))return 'Em acompanhamento';if(/andamento|suspenso/.test(exact))return 'Em andamento';return 'A classificar'}
function processParty(row){const exact=String(row.columnsByTitle?.['POSIÇÃO']||row.columns?.status||'').toLowerCase();if(/requerente|autor/.test(exact))return 'Requerente';if(/requerid|reclamad|réu|reu/.test(exact))return 'Requerida';return 'A classificar'}
function recordType(row){const c=row.columns||{},t=row.columnsByTitle||{};return String(t['TIPO DE AÇÃO']||t['TIPOS DE CONTRATO']||t['📋 Tipo de Honorário']||t['MODELOS DE NOTIFICAÇÃO']||c.tipo||c.tipo_processo||c.status8||c.status4||row.group||'Não informado').trim()||'Não informado'}
function recordStatus(row){const c=row.columns||{},t=row.columnsByTitle||{};return String(t["'MEU TRABALHO'"]||t['STATUS (para comitê)']||t.STATUS||t.Status||t.ESTÁGIOS||t['DISTRATO SIENGE/FINANCEIRO']||c.status84__1||c.status5||c.status||c.status4||'Não informado').trim()||'Não informado'}
function mondayDetails(row){const entries=Object.entries(row.columnsByTitle||{}).filter(([,v])=>String(v||'').trim());return entries.length?`<details><summary>Ver colunas do Monday (${entries.length})</summary><div>${entries.map(([k,v])=>`<div class="row"><b>${esc(k)}</b><span>${esc(v)}</span></div>`).join('')}</div></details>`:'<span class="muted">Sem valores preenchidos</span>'}
function checks(label,name,values){return `<div><label class="field-label">${esc(label)}</label><div class="checks">${values.map(v=>`<label class="check"><input type="checkbox" data-filter="${name}" value="${esc(v)}" onchange="applyLegalFilters()">${esc(v)}</label>`).join('')}</div></div>`}
function checked(name){return [...document.querySelectorAll(`[data-filter="${name}"]:checked`)].map(x=>x.value)}
function legalRows(){const key=LEGAL_KEY[state.legalModule]||state.legalModule;return state.legalData[key]?.records||[]}
function rowValue(row,kind){if(kind==='year')return recordYear(row);if(kind==='month')return recordMonth(row);if(kind==='enterprise')return recordEnterprise(row);if(kind==='responsible')return dashboardResponsible(row);if(kind==='type')return recordType(row);if(kind==='status')return state.legalModule==='processos'?processStatus(row):recordStatus(row);if(kind==='scope')return processScope(row);if(kind==='party')return processParty(row);return ''}
function filteredLegalRows(){const rows=legalRows(),kinds=['year','month','enterprise','responsible','type','status',...(state.legalModule==='processos'?['scope','party']:[])],selected=Object.fromEntries(kinds.map(k=>[k,checked(k)])),query=(document.getElementById('legal-search')?.value||'').toLowerCase().trim();return rows.filter(row=>kinds.every(k=>!selected[k].length||selected[k].includes(rowValue(row,k)))&&(!query||[row.title,row.group,...Object.values(row.columns||{}),...Object.values(row.columnsByTitle||{})].join(' ').toLowerCase().includes(query)))}
function applyLegalFilters(){const rows=filteredLegalRows(),all=legalRows();const count=document.getElementById('legal-count'),list=document.getElementById('legal-list');if(count)count.innerHTML=`Exibindo ${recordCount(rows.length)} de ${recordCount(all.length)} registros`;if(list)list.innerHTML=legalTable(rows)}
function clearLegalFilters(){document.querySelectorAll('[data-filter]').forEach(x=>x.checked=false);const q=document.getElementById('legal-search');if(q)q.value='';applyLegalFilters()}
function legalTable(rows){if(!rows.length)return '<div class="empty">Nenhum registro encontrado para este filtro.</div>';const process=state.legalModule==='processos';return `<div class="table-wrap"><table><thead><tr><th>Registro</th><th>Tipo</th><th>Empreendimento/Grupo</th><th>Responsável</th><th>Mês</th><th>Ano</th>${process?'<th>Polo</th><th>Escopo</th>':''}<th>Status</th><th>Colunas do Monday</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${esc(r.title||'Sem título')}</b></td><td>${esc(recordType(r))}</td><td>${esc(recordEnterprise(r))}</td><td>${esc(dashboardResponsible(r))}</td><td>${esc(recordMonth(r))}</td><td>${esc(recordYear(r))}</td>${process?`<td><span class="pill">${esc(processParty(r))}</span></td><td><span class="pill">${esc(processScope(r))}</span></td>`:''}<td><span class="pill">${esc(process?processStatus(r):recordStatus(r))}</span></td><td>${mondayDetails(r)}</td></tr>`).join('')}</tbody></table></div>`}
function processQueryString(){const params=new URLSearchParams({paginated:'1',page:String(state.processView.page),pageSize:String(state.processView.pageSize),sort:state.processView.sort,direction:state.processView.direction});for(const [kind,value] of Object.entries(state.processFilters)){if(kind==='search'){if(value)params.set('search',value);continue}for(const item of value||[])params.append(kind,item)}return params.toString()}
function syncProcessUrl(){const params=new URLSearchParams(processQueryString());params.delete('paginated');params.set('processos','1');history.replaceState(null,'',`${location.pathname}?${params.toString()}`)}
function restoreProcessFiltersFromUrl(){const params=new URLSearchParams(location.search);if(params.get('processos')!=='1')return;state.screen='juridico';state.legalModule='processos';for(const kind of ['status','enterprise','responsible','scope','year','type','month','party'])state.processFilters[kind]=params.getAll(kind);state.processFilters.responsible=[...new Set([...state.processFilters.responsible,...params.getAll('externalResponsible')])];state.processFilters.search=params.get('search')||'';state.processView.page=Math.max(1,Number(params.get('page'))||1);state.processView.pageSize=[25,50,100].includes(Number(params.get('pageSize')))?Number(params.get('pageSize')):25;state.processView.sort=params.get('sort')||'date';state.processView.direction=params.get('direction')==='asc'?'asc':'desc';if(params.has('externalResponsible')){params.delete('externalResponsible');params.delete('responsible');for(const name of state.processFilters.responsible)params.append('responsible',name);history.replaceState(null,'',`${location.pathname}?${params.toString()}`)}}
async function refreshProcessResults(){const target=document.getElementById('process-results');if(target)target.classList.add('is-loading');try{state.legalData.processos=await api(`/legal/processos?${processQueryString()}`);syncProcessUrl();app.innerHTML=page()}catch(error){if(target)target.innerHTML=`<div class="error">${esc(error.message)}</div>`}}
let processSearchTimer;
function debounceProcessSearch(value){clearTimeout(processSearchTimer);processSearchTimer=setTimeout(()=>{state.processFilters.search=value.trim();state.processView.page=1;refreshProcessResults()},350)}
function rememberProcessFilter(kind,open){if(open)state.processView.openFilter=kind;else if(state.processView.openFilter===kind)state.processView.openFilter=null}
function toggleProcessFilter(kind,value,checked){const current=new Set(state.processFilters[kind]||[]);checked?current.add(value):current.delete(value);state.processFilters[kind]=[...current];state.processView.page=1;state.processView.openFilter=kind;refreshProcessResults()}
function setProcessScope(value){state.processFilters.scope=value==='Todos'?[]:[value];state.processView.page=1;refreshProcessResults()}
function removeProcessFilter(kind,value){if(kind==='search')state.processFilters.search='';else state.processFilters[kind]=(state.processFilters[kind]||[]).filter(item=>item!==value);state.processView.page=1;refreshProcessResults()}
function clearProcessFilters(){state.processFilters={search:'',status:[],enterprise:[],responsible:[],scope:[],year:[],type:[],month:[],party:[]};state.processView.page=1;state.processView.openFilter=null;refreshProcessResults()}
function toggleAdvancedProcessFilters(){state.processView.advanced=!state.processView.advanced;app.innerHTML=page()}
function filterProcessOptions(input){const query=input.value.toLocaleLowerCase('pt-BR');input.closest('.process-filter-popover').querySelectorAll('.process-option').forEach(option=>option.hidden=!option.textContent.toLocaleLowerCase('pt-BR').includes(query))}
function processFilterLabel(kind,label){const count=(state.processFilters[kind]||[]).length;return count?`${label}: ${count} selecionado${count>1?'s':''}`:label}
function processMultiSelect(kind,label,options,searchable=false){const selected=new Set(state.processFilters[kind]||[]);return `<details class="process-filter-popover" ${state.processView.openFilter===kind?'open':''} ontoggle="rememberProcessFilter('${kind}',this.open)"><summary aria-label="Filtrar por ${esc(label)}">${esc(processFilterLabel(kind,label))}<span>⌄</span></summary><div class="process-filter-menu">${searchable?`<input class="process-option-search" aria-label="Pesquisar ${esc(label)}" placeholder="Pesquisar ${esc(label.toLowerCase())}" oninput="filterProcessOptions(this)">`:''}<div class="process-option-list">${options.map(option=>{const value=Array.isArray(option)?option[0]:option,optionLabel=Array.isArray(option)?option[1]:option;return `<label class="process-option"><input type="checkbox" ${selected.has(value)?'checked':''} onchange="toggleProcessFilter('${kind}','${esc(value)}',this.checked)"><span>${esc(optionLabel)}</span></label>`}).join('')||'<div class="muted">Sem opções disponíveis</div>'}</div></div></details>`}
function processActiveFilterCount(){return (state.processFilters.search?1:0)+['status','enterprise','responsible','scope','year','type','month','party'].reduce((sum,kind)=>sum+(state.processFilters[kind]?.length||0),0)}
function processActiveChips(){const labels={search:'Busca',status:'Status',enterprise:'Empreendimento',responsible:'Responsável',scope:'Escopo',year:'Ano',type:'Tipo',month:'Mês',party:'Polo'},chips=[];if(state.processFilters.search)chips.push(['search',state.processFilters.search]);for(const kind of ['status','enterprise','responsible','scope','year','type','month','party'])for(const value of state.processFilters[kind]||[])chips.push([kind,value]);if(!chips.length)return '';return `<div class="active-process-filters" aria-label="Filtros ativos"><span>Filtros ativos:</span>${chips.map(([kind,value])=>`<button onclick="removeProcessFilter('${kind}','${esc(value)}')" aria-label="Remover filtro ${esc(labels[kind])}: ${esc(value)}"><b>${esc(labels[kind])}:</b> ${esc(kind==='month'?processMonthName(value):value)} ×</button>`).join('')}<button class="clear-all-process" onclick="clearProcessFilters()">Limpar tudo</button></div>`}
function processMonthName(value){return DASHBOARD_MONTHS[Number(value)-1]||value}
function processResponsibleNames(row){const raw=dashboardColumn(row,'RESPONSÁVEL','person');return [...new Set(raw.split(',').map(value=>value.trim()).filter(Boolean))]}
function processExternalResponsibleNames(row){const local=dashboardColumn(row,'LOCAL','status3'),match=local.match(/^EXTERNO\s+(.+)$/i);if(!match)return [];return match[1].split(/[,;/]/).map(value=>value.trim().toLocaleLowerCase('pt-BR').replace(/(^|\s)\p{L}/gu,char=>char.toLocaleUpperCase('pt-BR'))).filter(Boolean)}
function processRelevantDate(row){return dashboardColumn(row,'DATA','data6')||dashboardColumn(row,'CITAÇÃO/PROTOCOLO','data8')||String(row.createdAt||'').slice(0,10)||'Não informada'}
function processDisplayYear(row){return String(row.title||'').match(/\.(20\d{2})\./)?.[1]||dashboardColumn(row,'CITAÇÃO/PROTOCOLO','data8')?.slice(0,4)||recordYear(row)}
function processBadge(value,kind){const slug=String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-');return `<span class="process-badge ${kind} ${slug}">${esc(value)}</span>`}
function processSortButton(field,label){const active=state.processView.sort===field,arrow=active?(state.processView.direction==='asc'?'↑':'↓'):'';return `<button class="sort-button" onclick="sortProcessTable('${field}')" aria-label="Ordenar por ${esc(label)}">${esc(label)} ${arrow}</button>`}
function sortProcessTable(field){if(state.processView.sort===field)state.processView.direction=state.processView.direction==='asc'?'desc':'asc';else{state.processView.sort=field;state.processView.direction='asc'}state.processView.page=1;refreshProcessResults()}
function setProcessPage(page){state.processView.page=page;refreshProcessResults()}
function setProcessPageSize(value){state.processView.pageSize=Number(value);state.processView.page=1;refreshProcessResults()}
async function copyProcessNumber(id){const row=(state.legalData.processos?.records||[]).find(item=>item.id===id);if(!row)return;await navigator.clipboard.writeText(row.title||'');const button=document.querySelector(`[data-copy-process="${id}"]`);if(button){button.textContent='Copiado';setTimeout(()=>button.textContent='Copiar',1200)}}
function showProcessTraceability(id){const row=(state.legalData.processos?.records||[]).find(item=>item.id===id),dialog=document.getElementById('process-traceability'),content=document.getElementById('process-trace-content');if(!row||!dialog||!content)return;const entries=Object.entries(row.columnsByTitle||{}).filter(([,value])=>String(value||'').trim());content.innerHTML=`<div class="trace-meta"><span>Origem</span><b>${esc(row.boardName||'Monday')}</b><span>Última sincronização</span><b>${esc(formatDateTime(row.syncedAt))}</b></div>${entries.map(([key,value])=>`<div class="row"><b>${esc(key)}</b><span>${esc(value)}</span></div>`).join('')}`;dialog.showModal()}
function processTable(data){const rows=data.records||[];if(!rows.length)return '<div class="dashboard-empty"><span class="empty-icon">◇</span><div><b>Nenhum processo encontrado</b><p>Revise os filtros ou limpe a consulta para visualizar a carteira.</p></div></div>';return `<div class="process-table-wrap"><table class="process-table"><thead><tr><th>${processSortButton('process','Processo')}</th><th>Tipo</th><th>${processSortButton('enterprise','Empreendimento')}</th><th>${processSortButton('responsible','Responsável')}</th><th>Polo</th><th>Escopo</th><th>${processSortButton('status','Status')}</th><th>${processSortButton('date','Data relevante')}</th><th>Ações</th></tr></thead><tbody>${rows.map(row=>{const responsible=[...new Set([...processResponsibleNames(row),...processExternalResponsibleNames(row)])];return `<tr><td data-label="Processo"><span class="process-number" title="${esc(row.title)}">${esc(row.title||'Sem número')}</span></td><td data-label="Tipo">${esc(recordType(row))}</td><td data-label="Empreendimento">${esc(recordEnterprise(row))}</td><td data-label="Responsável"><div class="responsible-stack">${esc(responsible.join(' · ')||'Não informado')}</div></td><td data-label="Polo">${processBadge(processParty(row),'party')}</td><td data-label="Escopo">${processBadge(processScope(row),'scope')}</td><td data-label="Status">${processBadge(processStatus(row),'status')}</td><td data-label="Data relevante"><span class="process-date">${esc(processRelevantDate(row))}</span><small>${esc(processDisplayYear(row))}</small></td><td data-label="Ações"><div class="process-actions"><button data-copy-process="${row.id}" onclick="copyProcessNumber('${row.id}')" aria-label="Copiar número do processo">Copiar</button><button onclick="showProcessTraceability('${row.id}')" aria-label="Ver rastreabilidade do processo">Origem</button></div></td></tr>`}).join('')}</tbody></table></div>`}
function processPagination(data){const pagination=data.pagination||{page:1,pageSize:25,totalPages:1};return `<div class="process-pagination"><label>Exibir <select onchange="setProcessPageSize(this.value)" aria-label="Registros por página">${[25,50,100].map(value=>`<option value="${value}" ${pagination.pageSize===value?'selected':''}>${value}</option>`).join('')}</select></label><span>Página ${pagination.page} de ${pagination.totalPages}</span><div><button onclick="setProcessPage(${pagination.page-1})" ${pagination.page<=1?'disabled':''} aria-label="Página anterior">Anterior</button><button onclick="setProcessPage(${pagination.page+1})" ${pagination.page>=pagination.totalPages?'disabled':''} aria-label="Próxima página">Próxima</button></div></div>`}
function advancedProcessDrawer(facets){return `<button class="process-drawer-overlay ${state.processView.advanced?'open':''}" onclick="toggleAdvancedProcessFilters()" aria-label="Fechar filtros avançados"></button><aside class="advanced-process-drawer ${state.processView.advanced?'open':''}" aria-hidden="${state.processView.advanced?'false':'true'}"><div class="advanced-drawer-head"><div><div class="eyebrow">Processos judiciais</div><h2>Filtros avançados</h2></div><button onclick="toggleAdvancedProcessFilters()" aria-label="Fechar filtros avançados">×</button></div><div class="advanced-filter-content">${processMultiSelect('type','Tipo de processo',facets.type||[],true)}${processMultiSelect('month','Mês',(facets.month||[]).map(value=>[value,processMonthName(value)]),false)}${processMultiSelect('party','Polo',facets.party||[],false)}</div><div class="advanced-drawer-footer"><button class="secondary" onclick="clearProcessFilters()">Limpar filtros</button><button class="primary" onclick="toggleAdvancedProcessFilters()">Ver resultados</button></div></aside>`}
function processJudicialPage(){const data=state.legalData.processos||{records:[],count:0,totalAvailable:0,pagination:{page:1,pageSize:25,totalPages:1},facets:{}},facets=data.facets||{},activeCount=processActiveFilterCount(),scope=state.processFilters.scope[0]||'Todos';const resultText=activeCount?`${recordCount(data.count)} de ${recordCount(data.totalAvailable)} registros`:`${recordCount(data.totalAvailable)} registros`;return shell(`<div class="process-page"><div class="process-page-head"><div><div class="eyebrow">Jurídico · Carteira processual</div><h2>Processos Judiciais</h2><div class="process-results-count">${resultText}</div></div></div><section class="compact-process-filters" aria-label="Filtros de processos"><div class="process-search"><label for="process-search">Busca</label><input id="process-search" value="${esc(state.processFilters.search)}" placeholder="Buscar por processo, empreendimento, responsável ou palavra-chave" oninput="debounceProcessSearch(this.value)"></div>${processMultiSelect('status','Status',facets.status||[])}${processMultiSelect('enterprise','Empreendimento',facets.enterprise||[],true)}${processMultiSelect('responsible','Responsável',facets.responsible||[],true)}<div class="scope-filter"><span>Escopo</span><div role="group" aria-label="Filtrar por escopo">${['Todos','Interno','Externo','A classificar'].map(value=>`<button class="${scope===value?'active':''}" onclick="setProcessScope('${value}')" aria-pressed="${scope===value}">${value}</button>`).join('')}</div></div>${processMultiSelect('year','Ano',facets.year||[])}<button class="more-process-filters" onclick="toggleAdvancedProcessFilters()" aria-expanded="${state.processView.advanced}">Mais filtros${activeCount?` <span>${activeCount}</span>`:''}</button>${activeCount?'<button class="clear-process-filters" onclick="clearProcessFilters()">Limpar</button>':''}</section>${processActiveChips()}<section class="card process-results" id="process-results"><div class="process-list-head"><div><b>${recordCount(data.count)} registro${data.count===1?'':'s'} encontrado${data.count===1?'':'s'}</b><span>${activeCount?'Consulta filtrada':'Carteira completa'}</span></div><span class="source-badge synced">Dados consolidados</span></div>${processTable(data)}${processPagination(data)}</section>${advancedProcessDrawer(facets)}<dialog id="process-traceability" class="traceability-dialog"><div class="advanced-drawer-head"><div><div class="eyebrow">Auditoria</div><h2>Rastreabilidade do processo</h2></div><button onclick="document.getElementById('process-traceability').close()" aria-label="Fechar rastreabilidade">×</button></div><div id="process-trace-content" class="trace-content"></div></dialog></div>`)}
function honorariumQueryString(){const params=new URLSearchParams({paginated:'1',page:String(state.honorariumView.page),pageSize:String(state.honorariumView.pageSize),sort:state.honorariumView.sort,direction:state.honorariumView.direction,summaryMode:state.honorariumView.summaryMode});if(state.honorariumFilters.search)params.set('search',state.honorariumFilters.search);for(const kind of ['status','enterprise','responsible','year','type','month','competence','paymentMethod','unit'])for(const value of state.honorariumFilters[kind]||[])params.append(kind,value);return params.toString()}
function syncHonorariumUrl(){const params=new URLSearchParams(honorariumQueryString());params.delete('paginated');params.set('honorarios','1');history.replaceState(null,'',`${location.pathname}?${params.toString()}`)}
function restoreHonorariumFiltersFromUrl(){const params=new URLSearchParams(location.search);if(params.get('honorarios')!=='1')return;state.screen='juridico';state.legalModule='honorarios';for(const kind of ['status','enterprise','responsible','year','type','month','competence','paymentMethod','unit'])state.honorariumFilters[kind]=params.getAll(kind);state.honorariumFilters.search=params.get('search')||'';state.honorariumView.page=Math.max(1,Number(params.get('page'))||1);state.honorariumView.pageSize=[25,50,100].includes(Number(params.get('pageSize')))?Number(params.get('pageSize')):25;state.honorariumView.sort=params.get('sort')||'date';state.honorariumView.direction=params.get('direction')==='asc'?'asc':'desc';state.honorariumView.summaryMode=['month','quarter','semester'].includes(params.get('summaryMode'))?params.get('summaryMode'):'month'}
function syncJudicialHonorariumUrl(){const params=new URLSearchParams({honorariosJudiciais:'1',summaryMode:state.honorariumView.summaryMode});history.replaceState(null,'',`${location.pathname}?${params.toString()}`)}
function restoreJudicialHonorariumFromUrl(){const params=new URLSearchParams(location.search);if(params.get('honorariosJudiciais')==='1'){state.screen='juridico';state.legalModule='honorarios-judiciais';state.honorariumView.summaryMode=['month','quarter','semester'].includes(params.get('summaryMode'))?params.get('summaryMode'):'month'}}
async function refreshHonorariumResults(){const target=document.getElementById('honorarium-results');if(target)target.classList.add('is-loading');try{state.legalData.honorarios=await api(`/legal/honorarios?${honorariumQueryString()}`);syncHonorariumUrl();app.innerHTML=page()}catch(error){if(target)target.innerHTML=`<div class="error">${esc(error.message)}</div>`}}
let honorariumSearchTimer;
function debounceHonorariumSearch(value){clearTimeout(honorariumSearchTimer);honorariumSearchTimer=setTimeout(()=>{state.honorariumFilters.search=value.trim();state.honorariumView.page=1;refreshHonorariumResults()},350)}
function rememberHonorariumFilter(kind,open){if(open)state.honorariumView.openFilter=kind;else if(state.honorariumView.openFilter===kind)state.honorariumView.openFilter=null}
function toggleHonorariumFilter(kind,value,checked){const current=new Set(state.honorariumFilters[kind]||[]);checked?current.add(value):current.delete(value);state.honorariumFilters[kind]=[...current];state.honorariumView.page=1;state.honorariumView.openFilter=kind;refreshHonorariumResults()}
function removeHonorariumFilter(kind,value){if(kind==='search')state.honorariumFilters.search='';else state.honorariumFilters[kind]=(state.honorariumFilters[kind]||[]).filter(item=>item!==value);state.honorariumView.page=1;refreshHonorariumResults()}
function clearHonorariumFilters(){state.honorariumFilters={search:'',status:[],enterprise:[],responsible:[],year:[],type:[],month:[],competence:[],paymentMethod:[],unit:[]};state.honorariumView.page=1;state.honorariumView.openFilter=null;refreshHonorariumResults()}
function toggleAdvancedHonorariumFilters(){state.honorariumView.advanced=!state.honorariumView.advanced;app.innerHTML=page()}
function honorariumFilterLabel(kind,label){const count=(state.honorariumFilters[kind]||[]).length;return count?`${label}: ${count} selecionado${count>1?'s':''}`:label}
function honorariumMultiSelect(kind,label,options,searchable=false){const selected=new Set(state.honorariumFilters[kind]||[]);return `<details class="process-filter-popover" ${state.honorariumView.openFilter===kind?'open':''} ontoggle="rememberHonorariumFilter('${kind}',this.open)"><summary aria-label="Filtrar por ${esc(label)}">${esc(honorariumFilterLabel(kind,label))}<span>⌄</span></summary><div class="process-filter-menu">${searchable?`<input class="process-option-search" aria-label="Pesquisar ${esc(label)}" placeholder="Pesquisar ${esc(label.toLowerCase())}" oninput="filterProcessOptions(this)">`:''}<div class="process-option-list">${options.map(option=>{const value=Array.isArray(option)?option[0]:option,optionLabel=Array.isArray(option)?option[1]:option;return `<label class="process-option"><input type="checkbox" ${selected.has(value)?'checked':''} onchange="toggleHonorariumFilter('${kind}','${esc(value)}',this.checked)"><span>${esc(optionLabel)}</span></label>`}).join('')||'<div class="muted">Sem opções cadastradas</div>'}</div></div></details>`}
function honorariumActiveFilterCount(){return(state.honorariumFilters.search?1:0)+['status','enterprise','responsible','year','type','month','competence','paymentMethod','unit'].reduce((sum,kind)=>sum+(state.honorariumFilters[kind]?.length||0),0)}
function honorariumActiveChips(){const labels={search:'Busca',status:'Status',enterprise:'Empreendimento',responsible:'Responsável',year:'Ano',type:'Tipo',month:'Mês',competence:'Competência',paymentMethod:'Forma de pagamento',unit:'Unidade'},chips=[];if(state.honorariumFilters.search)chips.push(['search',state.honorariumFilters.search]);for(const kind of ['status','enterprise','responsible','year','type','month','competence','paymentMethod','unit'])for(const value of state.honorariumFilters[kind]||[])chips.push([kind,value]);if(!chips.length)return '';return `<div class="active-process-filters" aria-label="Filtros ativos"><span>Filtros ativos:</span>${chips.map(([kind,value])=>`<button onclick="removeHonorariumFilter('${kind}','${esc(value)}')" aria-label="Remover filtro ${esc(labels[kind])}: ${esc(value)}"><b>${esc(labels[kind])}:</b> ${esc(kind==='month'?processMonthName(value):kind==='competence'?formatCompetence(value):value)} ×</button>`).join('')}<button class="clear-all-process" onclick="clearHonorariumFilters()">Limpar tudo</button></div>`}
function honorariumSortButton(field,label){const active=state.honorariumView.sort===field,arrow=active?(state.honorariumView.direction==='asc'?'↑':'↓'):'';return `<button class="sort-button" onclick="sortHonorariumTable('${field}')" aria-label="Ordenar por ${esc(label)}">${esc(label)} ${arrow}</button>`}
function sortHonorariumTable(field){if(state.honorariumView.sort===field)state.honorariumView.direction=state.honorariumView.direction==='asc'?'desc':'asc';else{state.honorariumView.sort=field;state.honorariumView.direction='asc'}state.honorariumView.page=1;refreshHonorariumResults()}
function setHonorariumPage(page){state.honorariumView.page=page;refreshHonorariumResults()}
function setHonorariumPageSize(value){state.honorariumView.pageSize=Number(value);state.honorariumView.page=1;refreshHonorariumResults()}
function honorariumPagination(data){const pagination=data.pagination||{page:1,pageSize:25,totalPages:1};return `<div class="process-pagination"><label>Exibir <select onchange="setHonorariumPageSize(this.value)" aria-label="Registros por página">${[25,50,100].map(value=>`<option value="${value}" ${pagination.pageSize===value?'selected':''}>${value}</option>`).join('')}</select></label><span>Página ${pagination.page} de ${pagination.totalPages}</span><div><button onclick="setHonorariumPage(${pagination.page-1})" ${pagination.page<=1?'disabled':''}>Anterior</button><button onclick="setHonorariumPage(${pagination.page+1})" ${pagination.page>=pagination.totalPages?'disabled':''}>Próxima</button></div></div>`}
function showHonorariumTraceability(id){const row=(state.legalData.honorarios?.records||[]).find(item=>item.id===id),dialog=document.getElementById('honorarium-traceability'),content=document.getElementById('honorarium-trace-content');if(!row||!dialog||!content)return;const entries=Object.entries(row.columnsByTitle||{}).filter(([,value])=>String(value||'').trim());content.innerHTML=`<div class="trace-meta"><span>Origem</span><b>${esc(row.boardName||'Monday')}</b><span>Identificador original</span><b>${esc(row.externalId||'Não informado')}</b><span>Última sincronização</span><b>${esc(formatDateTime(row.syncedAt))}</b></div>${entries.map(([key,value])=>`<div class="row"><b>${esc(key)}</b><span>${esc(value)}</span></div>`).join('')}`;dialog.showModal()}
function honorariumTable(data){const rows=data.records||[];if(!rows.length)return '<div class="dashboard-empty"><span class="empty-icon">◇</span><div><b>Nenhum honorário encontrado</b><p>Revise os filtros ou limpe a consulta para visualizar os registros.</p></div></div>';return `<div class="process-table-wrap"><table class="process-table honorarium-table"><thead><tr><th>Registro</th><th>${honorariumSortButton('status','Status')}</th><th>${honorariumSortButton('enterprise','Empreendimento')}</th><th>${honorariumSortButton('responsible','Responsável')}</th><th>Tipo de honorário</th><th>${honorariumSortButton('competence','Competência')}</th><th>${honorariumSortButton('amount','Valor')}</th><th>Ações</th></tr></thead><tbody>${rows.map(row=>{const view=row.normalized||{};return `<tr><td data-label="Registro"><b>${esc(row.title||'Sem título')}</b></td><td data-label="Status">${processBadge(view.status||'Não informado','status')}</td><td data-label="Empreendimento">${esc(view.enterprise||'Não informado')}</td><td data-label="Responsável"><div class="responsible-stack">${esc((view.responsibles||[]).join(' · ')||'Não informado')}</div></td><td data-label="Tipo de honorário">${esc(view.type||'Não informado')}</td><td data-label="Competência"><b>${esc(formatCompetence(view.competence))}</b><small>${esc(view.date||'')}</small></td><td data-label="Valor">${Number.isFinite(view.amount)?money(view.amount):'Não informado'}</td><td data-label="Ações"><div class="process-actions"><button onclick="showHonorariumTraceability('${row.id}')">Origem</button></div></td></tr>`}).join('')}</tbody></table></div>`}
function advancedHonorariumDrawer(facets){return `<button class="process-drawer-overlay ${state.honorariumView.advanced?'open':''}" onclick="toggleAdvancedHonorariumFilters()" aria-label="Fechar filtros avançados"></button><aside class="advanced-process-drawer ${state.honorariumView.advanced?'open':''}" aria-hidden="${state.honorariumView.advanced?'false':'true'}"><div class="advanced-drawer-head"><div><div class="eyebrow">Honorários extrajudiciais</div><h2>Filtros avançados</h2></div><button onclick="toggleAdvancedHonorariumFilters()" aria-label="Fechar filtros avançados">×</button></div><div class="advanced-filter-content">${honorariumMultiSelect('type','Tipo de honorário',facets.type||[],true)}${!(facets.type||[]).length?'<p class="filter-schema-note">O campo próprio de tipo existe no Monday, mas ainda não possui valores. As competências não são tratadas como tipo.</p>':''}${honorariumMultiSelect('competence','Competência',(facets.competence||[]).map(value=>[value,formatCompetence(value)]),true)}${honorariumMultiSelect('month','Mês',(facets.month||[]).map(value=>[value,processMonthName(value)]))}${honorariumMultiSelect('paymentMethod','Forma de pagamento',facets.paymentMethod||[],true)}${honorariumMultiSelect('unit','Unidade',facets.unit||[],true)}</div><div class="advanced-drawer-footer"><button class="secondary" onclick="clearHonorariumFilters()">Limpar filtros</button><button class="primary" onclick="toggleAdvancedHonorariumFilters()">Ver resultados</button></div></aside>`}
const honorariumMoney=value=>Number.isFinite(Number(value))?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(value)):'Não informado';
function honorariumPeriodLabel(key,mode){if(mode==='month')return formatCompetence(key);const match=String(key).match(/^(\d{4})-[TS](\d)$/);if(!match)return key;return mode==='quarter'?`${match[2]}º trimestre/${match[1]}`:`${match[2]}º semestre/${match[1]}`}
function setHonorariumSummaryMode(mode){state.honorariumView.summaryMode=mode;state.legalModule==='honorarios-judiciais'?syncJudicialHonorariumUrl():syncHonorariumUrl();app.innerHTML=page()}
function honorariumFinancialSummary(data){const summary=data.summary||{total:0,recordsWithAmount:0,average:null,months:[],quarters:[],semesters:[]},mode=state.honorariumView.summaryMode,rows=(mode==='quarter'?summary.quarters:mode==='semester'?summary.semesters:summary.months)||[],limit=mode==='month'?12:8;return `<section class="honorarium-summary" aria-label="Resumo financeiro de honorários"><div class="honorarium-total-card"><span>Total do recorte filtrado</span><strong>${honorariumMoney(summary.total)}</strong><small>${Number(summary.recordsWithAmount||0).toLocaleString('pt-BR')} registros com valor · média ${honorariumMoney(summary.average)}</small></div><div class="honorarium-period-summary"><div class="honorarium-summary-head"><div><span>Totais por período</span><small>Os valores acompanham todos os filtros ativos.</small></div><div class="honorarium-period-tabs" role="group" aria-label="Agrupar totais por período">${[['month','Mês'],['quarter','Trimestre'],['semester','Semestre']].map(([value,label])=>`<button class="${mode===value?'active':''}" onclick="setHonorariumSummaryMode('${value}')" aria-pressed="${mode===value}">${label}</button>`).join('')}</div></div><div class="honorarium-period-cards">${rows.slice(0,limit).map(item=>`<article><span>${esc(honorariumPeriodLabel(item.key,mode))}</span><strong>${honorariumMoney(item.total)}</strong><small>${Number(item.count||0).toLocaleString('pt-BR')} registro${item.count===1?'':'s'}</small></article>`).join('')||'<div class="dashboard-empty"><span class="empty-icon">◇</span><div><b>Sem valores no recorte</b><p>Os registros filtrados não possuem valores financeiros preenchidos.</p></div></div>'}</div>${rows.length>limit?`<small class="honorarium-summary-limit">Exibindo os ${limit} períodos mais recentes.</small>`:''}</div></section>`}
function honorariumPage(){const data=state.legalData.honorarios||{records:[],count:0,totalAvailable:0,pagination:{page:1,pageSize:25,totalPages:1},facets:{},summary:{}},facets=data.facets||{},activeCount=honorariumActiveFilterCount(),resultText=`${recordCount(data.count)} de ${recordCount(data.totalAvailable)} registros`,sync=data.lastSyncedAt?formatDateTime(data.lastSyncedAt):'não disponível';return shell(`<div class="process-page honorarium-page"><div class="process-page-head"><div><div class="eyebrow">Jurídico · Financeiro extrajudicial</div><h2>Honorários Extrajudiciais</h2><div class="process-results-count">${resultText} · Dados consolidados · Última sincronização: ${esc(sync)}</div></div><button class="secondary" onclick="state.legalModule=null;render()">Voltar às pastas</button></div><section class="compact-process-filters honorarium-filter-bar" aria-label="Filtros de honorários"><div class="process-search"><label for="honorarium-search">Busca</label><input id="honorarium-search" value="${esc(state.honorariumFilters.search)}" placeholder="Buscar registro, empreendimento ou responsável" oninput="debounceHonorariumSearch(this.value)"></div>${honorariumMultiSelect('status','Status',facets.status||[],true)}${honorariumMultiSelect('enterprise','Empreendimento',facets.enterprise||[],true)}${honorariumMultiSelect('responsible','Responsável',facets.responsible||[],true)}${honorariumMultiSelect('year','Ano',facets.year||[])}<button class="more-process-filters" onclick="toggleAdvancedHonorariumFilters()" aria-expanded="${state.honorariumView.advanced}">Mais filtros${activeCount?` <span>${activeCount}</span>`:''}</button>${activeCount?'<button class="clear-process-filters" onclick="clearHonorariumFilters()">Limpar</button>':''}</section>${honorariumActiveChips()}${honorariumFinancialSummary(data)}<section class="card process-results" id="honorarium-results"><div class="process-list-head"><div><b>${recordCount(data.count)} de ${recordCount(data.totalAvailable)} registros</b><span>${activeCount?'Consulta filtrada':'Base completa'}</span></div><span class="source-badge synced">Dados consolidados</span></div>${honorariumTable(data)}${honorariumPagination(data)}</section>${advancedHonorariumDrawer(facets)}<dialog id="honorarium-traceability" class="traceability-dialog"><div class="advanced-drawer-head"><div><div class="eyebrow">Auditoria</div><h2>Origem do registro</h2></div><button onclick="document.getElementById('honorarium-traceability').close()" aria-label="Fechar rastreabilidade">×</button></div><div id="honorarium-trace-content" class="trace-content"></div></dialog></div>`)}
function showJudicialHonorariumTraceability(id){const row=(state.legalData.honorariosJudiciais?.records||[]).find(item=>item.id===id),dialog=document.getElementById('judicial-honorarium-traceability'),content=document.getElementById('judicial-honorarium-trace-content');if(!row||!dialog||!content)return;const entries=Object.entries(row.columnsByTitle||{}).filter(([,value])=>String(value||'').trim());content.innerHTML=`<div class="trace-meta"><span>Origem</span><b>${esc(row.boardName||'Monday · Processos Judiciais')}</b><span>Identificador original</span><b>${esc(row.externalId||'Não informado')}</b><span>Última sincronização</span><b>${esc(formatDateTime(row.syncedAt))}</b></div>${entries.map(([key,value])=>`<div class="row"><b>${esc(key)}</b><span>${esc(value)}</span></div>`).join('')}`;dialog.showModal()}
function judicialHonorariumPage(){const data=state.legalData.honorariosJudiciais||{records:[],count:0,summary:{total:0,recordsWithAmount:0,average:null,months:[],quarters:[],semesters:[]}},sync=data.lastSyncedAt?formatDateTime(data.lastSyncedAt):'não disponível';return shell(`<div class="process-page honorarium-page"><div class="process-page-head"><div><div class="eyebrow">Jurídico · Financeiro judicial</div><h2>Honorários Judiciais</h2><div class="process-results-count">${recordCount(data.count)} processos com honorários efetivados · Última sincronização: ${esc(sync)}</div></div><button class="secondary" onclick="state.legalModule=null;render()">Voltar às pastas</button></div>${honorariumFinancialSummary(data)}<section class="card process-results"><div class="process-list-head"><div><b>${recordCount(data.count)} processos encontrados</b><span>Fonte: campo “HONORÁRIOS EFETIVADOS” dos processos judiciais</span></div><span class="source-badge synced">Dados consolidados</span></div><div class="process-table-wrap"><table class="process-table judicial-honorarium-table"><thead><tr><th>Processo</th><th>Empreendimento</th><th>Responsável</th><th>Tipo de ação</th><th>Status</th><th>Data</th><th>Honorários efetivados</th><th>Ações</th></tr></thead><tbody>${(data.records||[]).map(row=>{const view=row.normalized||{};return `<tr><td data-label="Processo"><b>${esc(row.title||'Sem número')}</b></td><td data-label="Empreendimento">${esc(view.enterprise||'Não informado')}</td><td data-label="Responsável">${esc((view.responsibles||[]).join(' · ')||'Não informado')}</td><td data-label="Tipo de ação">${esc(view.type||'Não informado')}</td><td data-label="Status">${processBadge(view.status||'Não informado','status')}</td><td data-label="Data">${esc(view.date||'Não informada')}</td><td data-label="Honorários efetivados"><b>${honorariumMoney(view.amount)}</b></td><td data-label="Ações"><div class="process-actions"><button onclick="showJudicialHonorariumTraceability('${row.id}')">Origem</button></div></td></tr>`}).join('')}</tbody></table></div></section><dialog id="judicial-honorarium-traceability" class="traceability-dialog"><div class="advanced-drawer-head"><div><div class="eyebrow">Auditoria</div><h2>Origem do registro judicial</h2></div><button onclick="document.getElementById('judicial-honorarium-traceability').close()" aria-label="Fechar rastreabilidade">×</button></div><div id="judicial-honorarium-trace-content" class="trace-content"></div></dialog></div>`)}
function legalDetailPage(){if(state.legalModule==='processos')return processJudicialPage();if(state.legalModule==='honorarios')return honorariumPage();if(state.legalModule==='honorarios-judiciais')return judicialHonorariumPage();const item=LEGAL_MODULES.find(m=>m[0]===state.legalModule)||[state.legalModule,state.legalModule,''],rows=legalRows();const values=kind=>[...new Set(rows.map(r=>rowValue(r,kind)))].filter(v=>v&&v!=='Não informado').sort((a,b)=>String(a).localeCompare(String(b),'pt-BR'));return shell(`<div class="notice">Dados jurídicos sincronizados e consolidados na COEVO Alta Performance.</div><div class="section-title"><div><div class="eyebrow">Jurídico · ${esc(item[1])}</div><h2>${esc(item[1])}</h2><div class="muted" id="legal-count">Exibindo ${recordCount(rows.length)} de ${recordCount(rows.length)} registros</div></div><button class="secondary" onclick="state.legalModule=null;render()">Voltar às pastas</button></div><section class="card"><div class="section-title"><h2>Filtros múltiplos</h2><button class="secondary" onclick="clearLegalFilters()">Limpar filtros</button></div><div class="filter-grid">${checks('Tipo','type',values('type'))}${checks('Ano','year',values('year'))}${checks('Mês','month',DASHBOARD_MONTHS)}${checks('Empreendimento/Grupo','enterprise',values('enterprise'))}${checks('Responsável','responsible',values('responsible'))}${checks('Status','status',values('status'))}<div><label class="field-label" for="legal-search">Pesquisar</label><input class="input" id="legal-search" placeholder="Título ou palavra-chave" oninput="applyLegalFilters()"></div></div></section><section class="card section" id="legal-list">${legalTable(rows)}</section>`)}

function dashboardIdForScreen(screen){return ({executivo:'executive',ti:'ti',engenharia:'engineering',estrategia:'strategy',riscos:'risks'})[screen]||null}
function configuredDashboardPage(){const payload=state.configuredDashboard;if(!payload)return shell('<div class="notice">Dashboard ainda não carregado.</div>');const title=payload.dashboard.name;return shell(`<section class="dashboard-config-head"><div><div class="eyebrow">Dashboard configurável</div><h1>${esc(title)}</h1><p>Indicadores agregados, permissões por perfil e memória de cálculo em cada componente.</p></div><div class="dashboard-config-actions"><button onclick="toggleDashboardPersonalization()">${state.dashboardPersonalizing?'Concluir':'Personalizar'}</button></div></section>${window.CoevoDashboardWidgets.dashboard(payload,state.dashboardPreference||{},{personalizing:state.dashboardPersonalizing})}`)}
function toggleDashboardPersonalization(){state.dashboardPersonalizing=!state.dashboardPersonalizing;app.innerHTML=page()}
async function toggleDashboardWidget(id){const hidden=new Set(state.dashboardPreference?.hiddenWidgets||[]);hidden.has(id)?hidden.delete(id):hidden.add(id);state.dashboardPreference={...(state.dashboardPreference||{}),hiddenWidgets:[...hidden]};app.innerHTML=page();const dashboardId=dashboardIdForScreen(state.screen);if(dashboardId)state.dashboardPreference=await api(`/dashboard-preferences/${dashboardId}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(state.dashboardPreference)})}
function openWidgetTarget(target){if(target==='legal'){go('juridico');return}if(target==='ti'){go('ti');return}if(target==='processos'){state.screen='juridico';state.legalModule='processos';render();return}if(LEGAL_KEY[target]||LEGAL_MODULES.some(([id])=>id===target)){state.screen='juridico';state.legalModule=Object.entries(LEGAL_KEY).find(([,key])=>key===target)?.[0]||target;render();return}}
function tiPage(){return configuredDashboardPage()}
function projectStatus(status){const tone=status==='Concluído'?'green':status==='Em andamento'?'blue':'amber';return `<span class="project-status ${tone}">${esc(status||'Não informado')}</span>`}
function projectUnavailable(label,indicator){return `<article class="project-kpi unavailable"><span>${esc(label)}</span><strong>Dados ainda não disponíveis</strong><small>${esc(indicator?.status||'Aguardando integração')}</small></article>`}
function projectPortfolioPage(){const projects=state.projects?.projects||[];return shell(`<section class="project-page-head"><div><div class="eyebrow">Dashboard de Projetos</div><h1>Projetos estratégicos</h1><p>Iniciativas reais, com governança, metas, riscos, marcos e resultados rastreáveis.</p></div><span class="project-total">${recordCount(projects.length)} projeto${projects.length===1?'':'s'}</span></section><section class="project-portfolio">${projects.length?projects.map(project=>`<button class="project-card" onclick="openProject('${project.id}')"><div class="project-card-top"><span>${esc(project.department)} · ${esc(project.category)} · Eficiência financeira</span>${projectStatus(project.status)}</div><h2>${esc(project.name)}</h2><p>${esc(project.objective)}</p><div class="project-card-grid"><div><span>Responsável</span><b>${esc(project.owner?.name||'Não definido')}</b></div><div><span>Progresso</span><b>${Number.isFinite(project.progress)?`${project.progress.toFixed(0)}%`:'Aguardando medição'}</b></div><div><span>Meta</span><b>${project.target?'Configurada':'Ainda não cadastrada'}</b></div><div><span>Resultado atual</span><b>Dados ainda não disponíveis</b></div><div><span>Risco</span><b>${project.riskCount?`${project.riskCount} risco(s) ativo(s)`:'Nenhum risco cadastrado'}</b></div><div><span>Próximo marco</span><b>${esc(project.nextMilestone?.title||'Aguardando planejamento')}</b></div></div><span class="project-open">Abrir projeto →</span></button>`).join(''):'<div class="dashboard-empty">Nenhum projeto cadastrado.</div>'}</section>`)}
function projectPerson(role,person,description){return `<article class="project-person"><span>${esc(role)}</span><strong>${esc(person?.name||'Não definido')}</strong><small>${esc(description)}</small></article>`}
function projectList(items,kind){if(!items.length)return '<div class="project-empty">Nenhum registro real cadastrado.</div>';return `<div class="project-list">${items.map(item=>`<article><div><b>${esc(item.title||item.name||'Registro')}</b><small>${esc(item.notes||item.expectedResult||'Sem observação')}</small></div>${projectStatus(item.status)}</article>`).join('')}</div>`}
function projectTargetPanel(data){const target=data.target,indicator=target?data.indicators.find(item=>item.id===target.indicatorId):null,current=indicator?.value,gap=Number.isFinite(current)&&Number.isFinite(Number(target?.targetValue))?Number(target.targetValue)-Number(current):null;const show=value=>Number.isFinite(Number(value))?Number(value).toLocaleString('pt-BR',{maximumFractionDigits:2}):'Dados ainda não disponíveis';return `<section id="meta" class="project-section"><div class="project-section-title"><div><span>Meta do projeto</span><h2>${esc(indicator?.name||'Indicador principal ainda não definido')}</h2></div><small>Editável pela gestora</small></div><div class="target-grid"><article><span>Atual</span><b>${show(current)}</b></article><article><span>Baseline</span><b>${show(target?.baseline)}</b></article><article><span>Meta</span><b>${show(target?.targetValue)}</b></article><article><span>Gap</span><b>${show(gap)}</b></article><article><span>Tendência</span><b>Aguardando histórico</b></article><article><span>Prazo</span><b>${esc(target?.dueDate||'Não definido')}</b></article></div></section>`}
function projectCharts(data){const charts=[['Recuperação mensal','Linha · Mês x valor recuperado','monthlyRecovery'],['Interno x externo','Barras · Taxa, valor, tempo e custo','internalVsExternal'],['Aging da carteira','Barras por faixa configurável','aging'],['Funil de recuperação','Carteira → contato → negociação → proposta → acordo → recebido','funnel'],['Recuperação por empreendimento','Barras horizontais','byEnterprise']];return `<section id="graficos" class="project-section"><div class="project-section-title"><div><span>Análises</span><h2>Gráficos do projeto</h2></div><small>Exibidos quando houver histórico real</small></div><div class="project-chart-grid">${charts.map(([title,description,key])=>`<article><div><b>${esc(title)}</b><small>${esc(description)}</small></div>${data.chartSeries?.[key]?.length?'<div class="project-chart-ready">Dados disponíveis</div>':'<div class="project-chart-empty">Aguardando integração</div>'}</article>`).join('')}</div></section>`}
function projectManagementItems(items){if(!items.length)return '<div class="project-empty positive"><b>Nenhuma pendência para gestão.</b><span>Somente decisões realmente escalonadas aparecerão aqui.</span></div>';return `<div class="management-list">${items.map(item=>`<button onclick="openProjectManagementTarget('${esc(item.sourceModule||'')}','${esc(item.sourceId||'')}')"><span>${esc(item.type||'Decisão')}</span><b>${esc(item.title)}</b><small>${esc(item.reason||'Requer acompanhamento gerencial')}</small></button>`).join('')}</div>`}
function projectDetailPage(){const data=state.projectDetail;if(!data)return shell('<div class="notice">Projeto ainda não carregado.</div>');const p=data.project,indicator=name=>data.indicators.find(item=>item.name===name);const kpis=['Carteira inadimplente','Valor recuperado no mês','Valor recuperado acumulado','Taxa de recuperação','Processos internalizados','Número de acordos','Honorários gerados','Resultado líquido'];return shell(`<button class="project-back" onclick="closeProject()">← Voltar ao Dashboard de Projetos</button><section class="project-hero"><div><div class="eyebrow">Projeto estratégico · Jurídico</div><h1>${esc(p.name)}</h1><p>${esc(p.objective)}</p></div>${projectStatus(p.status)}</section><section class="project-governance">${projectPerson('Responsável operacional',p.owner,'Execução, acompanhamento, prazos e tratativas.')}${projectPerson('Gestão',p.manager,'Estratégia, metas, riscos, desvios e aprovações por alçada.')}${projectPerson('Patrocínio executivo',p.sponsor,'Pode ser definido posteriormente, sem alterar a gestão atual.')}</section><section class="project-overview"><article><span>Status</span><b>${esc(p.status)}</b></article><article><span>Meta principal</span><b>${data.target?'Meta configurada':'Meta ainda não cadastrada'}</b></article><article><span>Progresso real</span><b>${Number.isFinite(p.progress)?`${p.progress.toFixed(1)}%`:'Aguardando medição'}</b></article><article><span>Prazo</span><b>${esc(data.target?.dueDate||p.nextMilestone?.targetDate||'Não definido')}</b></article><article><span>Objetivo estratégico</span><b>${esc(data.strategicObjective?.title||'Não definido')}</b></article><article><span>Próximo marco</span><b>${esc(p.nextMilestone?.title||'Aguardando planejamento')}</b></article></section><nav class="project-section-nav"><a href="#meta">Meta</a><a href="#indicadores">Indicadores</a><a href="#gestao">Pendências</a><a href="#plano">Plano de ação</a><a href="#internalizacao">Internalização</a><a href="#negociacoes">Negociações</a><a href="#advogados">Advogados</a><a href="#graficos">Gráficos</a><a href="#governanca">Alçadas</a><a href="#fontes">Fontes</a></nav>${projectTargetPanel(data)}<section id="indicadores" class="project-section"><div class="project-section-title"><div><span>Indicadores</span><h2>Resultado da recuperação</h2></div><small>Sem dados simulados</small></div><div class="project-kpis">${kpis.map(name=>{const item=indicator(name);return Number.isFinite(item?.value)?`<article class="project-kpi"><span>${esc(name)}</span><strong>${item.unit==='currency'?money(item.value):item.unit==='percent'?`${item.value}%`:Number(item.value).toLocaleString('pt-BR')}</strong><small>${esc(item.source||'Fonte registrada')}</small></article>`:projectUnavailable(name,item)}).join('')}</div></section><section id="gestao" class="project-section attention"><div class="project-section-title"><div><span>Pendências para gestão</span><h2>Atenção da gestora</h2></div><b>${data.managementItems.length}</b></div>${projectManagementItems(data.managementItems)}</section><div class="project-two"><section id="plano" class="project-section"><div class="project-section-title"><div><span>Execução</span><h2>Plano de ação</h2></div><b>${data.actions.length}</b></div>${projectList(data.actions,'action')}</section><section class="project-section"><div class="project-section-title"><div><span>Entregas</span><h2>Marcos</h2></div><b>${data.milestones.length}</b></div>${projectList(data.milestones,'milestone')}</section></div><section class="project-section"><div class="project-section-title"><div><span>Frentes estratégicas</span><h2>Estrutura de trabalho</h2></div><b>${data.workstreams.length}</b></div><div class="workstream-grid">${data.workstreams.map((item,index)=>`<article><span>${String(index+1).padStart(2,'0')}</span><b>${esc(item.title)}</b><small>${esc(item.status)}</small></article>`).join('')}</div></section><div class="project-two"><section id="internalizacao" class="project-section"><div class="project-section-title"><div><span>Decisão baseada em dados</span><h2>Internalização</h2></div><b>${data.internalizations.length}</b></div>${projectList(data.internalizations,'internalization')}<p class="project-note">Nenhum processo será considerado interno ou externo neste projeto sem relacionamento explícito e decisão registrada.</p></section><section class="project-section"><div class="project-section-title"><div><span>Performance</span><h2>Recuperação interna x externa</h2></div></div><div class="project-empty">Aguardando histórico financeiro conciliado para comparar valor, taxa, tempo, custo, honorários e resultado líquido.</div></section></div><div class="project-two"><section id="negociacoes" class="project-section"><div class="project-section-title"><div><span>Carteira</span><h2>Negociações</h2></div><b>${data.negotiations.length}</b></div>${projectList(data.negotiations,'negotiation')}</section><section id="advogados" class="project-section"><div class="project-section-title"><div><span>Histórico processual</span><h2>Advogados e tratativas jurídicas</h2></div><b>${data.legalTreatments.length}</b></div>${projectList(data.legalTreatments,'legal-treatment')}</section></div>${projectCharts(data)}<section class="project-section"><div class="project-section-title"><div><span>Controle</span><h2>Riscos</h2></div><b>${data.risks.length}</b></div>${projectList(data.risks,'risk')}</section><section id="governanca" class="project-section"><div class="project-section-title"><div><span>Governança</span><h2>Alçadas e escalonamento</h2></div><small>Responsável → Gestora → aprovação superior</small></div><div class="approval-flow"><article><span>Execução</span><b>${esc(p.owner?.name)}</b></article><i>→</i><article><span>Gestão</span><b>${esc(p.manager?.name)}</b></article><i>→</i><article><span>Aprovação</span><b>Conforme regra configurada</b></article></div>${data.approvalRules.map(rule=>`<div class="approval-rule"><div><b>${esc(rule.name)}</b><small>Versão ${rule.version} · ${rule.active?'Ativa':'Inativa'}</small></div><span>${rule.levels.length?`${rule.levels.length} níveis`:'Limites ainda não cadastrados'}</span></div>`).join('')}<p class="project-note">Desconto, entrada, parcelas e faixas de dívida são parametrizáveis. Nenhum valor foi fixado no código.</p></section><section id="fontes" class="project-section"><div class="project-section-title"><div><span>Qualidade e integração</span><h2>Fontes conectadas</h2></div></div><div class="source-readiness">${Object.entries(data.sourceReadiness).map(([key,value])=>`<article><span>${esc(({processes:'Processos',extrajudicialHonorariums:'Honorários extrajudiciais',sienge:'Sienge',recovery:'Recuperação'})[key]||key)}</span><b>${Number(value.records).toLocaleString('pt-BR')} registros</b><small>${esc(value.status)}</small></article>`).join('')}</div></section>`)}
function projectsPage(){return state.selectedProjectId?projectDetailPage():projectPortfolioPage()}
async function openProject(id){state.selectedProjectId=id;history.replaceState(null,'',`?project=${encodeURIComponent(id)}`);state.projectDetail=await api(`/projects/${id}`);app.innerHTML=page()}
function closeProject(){state.selectedProjectId=null;state.projectDetail=null;history.replaceState(null,'',location.pathname);app.innerHTML=page()}
function openProjectManagementTarget(module,id){if(module&&LEGAL_MODULES.some(item=>item[0]===module)){state.screen='juridico';state.legalModule=module;state.selectedProjectId=null;history.replaceState(null,'',location.pathname);render();return}if(id)location.hash=`registro-${encodeURIComponent(id)}`}
function openRecoveryProject(){state.screen='projetos';state.selectedProjectId='prj-aumento-recuperacao-credito';state.legalModule=null;history.replaceState(null,'',`?project=${encodeURIComponent(state.selectedProjectId)}`);render()}
function aiPage(){return shell(`<div class="notice">IA como copiloto verificável, com confirmação humana para ações de alto impacto.</div><div class="grid"><div class="card"><div class="eyebrow">Visão COEVO</div><h2>IA Executiva</h2><p class="muted">Indicadores, riscos, orçamento e decisões.</p></div><div class="card"><div class="eyebrow">Jurídico</div><h2>Têmis</h2><p class="muted">Processos, contratos, notificações e riscos.</p></div><div class="card"><div class="eyebrow">Tecnologia</div><h2>Ivo</h2><p class="muted">Projetos, chamados, ativos e segurança.</p></div></div>`)}
function agendaPage(){return shell(`<section class="card"><div class="section-title"><h2>Agenda</h2><span class="pill">${state.dashboard.upcoming.length} compromissos</span></div>${state.dashboard.upcoming.map(e=>`<div class="row"><div><b>${esc(e.title)}</b><div class="muted">${esc(e.department)} · ${esc(e.owner)} · ${esc(e.classification)}</div></div><span>${esc(e.date)} <span class="pill">${esc(e.status)}</span></span></div>`).join('')}</section>`)}
function calculatorPage(){return shell(`<section class="card"><div class="section-title"><h2>Calculadora</h2></div><div class="grid"><div><label class="field-label">Primeiro valor</label><input class="input" id="calc-a" type="number" step="any" value="0"></div><div><label class="field-label">Operação</label><select class="input" id="calc-op"><option value="+">Somar</option><option value="-">Subtrair</option><option value="*">Multiplicar</option><option value="/">Dividir</option></select></div><div><label class="field-label">Segundo valor</label><input class="input" id="calc-b" type="number" step="any" value="0"></div></div><button class="primary section" onclick="calculate()">Calcular</button><div class="card section"><div class="muted">Resultado</div><div class="calc-result" id="calc-result">0</div></div></section>`)}
function calculate(){const a=Number(document.getElementById('calc-a').value||0),b=Number(document.getElementById('calc-b').value||0),op=document.getElementById('calc-op').value;const result=op==='+'?a+b:op==='-'?a-b:op==='*'?a*b:b===0?'Não é possível dividir por zero':a/b;document.getElementById('calc-result').textContent=typeof result==='number'?result.toLocaleString('pt-BR',{maximumFractionDigits:2}):result}
function committeePage(){const department=state.committeeDepartment||'COEVO';return shell(`<div class="notice">Comitês e apresentações · ${esc(department)}.</div><div class="grid"><div class="card"><h2>Pauta e tópicos</h2><p class="muted">Orçamento, riscos, prazos, indicadores e anexos.</p></div><div class="card"><h2>Apresentação executiva</h2><p class="muted">Público, profundidade, classificação e exportação.</p></div><div class="card"><h2>Ata e decisões</h2><p class="muted">Responsável, prazo, contexto e evidência.</p></div></div>`)}
function auditPage(){return shell(`<div class="notice">Aprovação de acessos sob responsabilidade de Cristiane Carneiro Rabelo.</div><section class="card"><div class="section-title"><h2>Cadastros pendentes</h2><button class="secondary" onclick="loadApprovals()">Atualizar</button></div><div id="approval-list" class="empty">Carregando…</div></section>`)}
async function loadApprovals(){const target=document.getElementById('approval-list');if(!target)return;try{const rows=await api('/auth/requests');const pending=rows.filter(r=>r.status==='pending');target.innerHTML=pending.length?pending.map(r=>`<div class="row"><div><b>${esc(r.name)}</b><div class="muted">${esc(r.email)} · ${esc(r.department)}</div></div><button class="primary" onclick="approveRegistration('${esc(r.id)}')">Aprovar</button></div>`).join(''):'Nenhum cadastro pendente.'}catch(error){target.innerHTML=`<div class="error">${esc(error.message)}</div>`}}
async function approveRegistration(id){await api(`/auth/requests/${id}/approve`,{method:'POST'});loadApprovals()}
function executiveFinanceBlock(finance,notifications=0){if(!finance)return `<section class="card"><div class="empty">Dados ainda não disponíveis.</div></section>`;return `<section class="card finance-department"><div class="section-title"><div><div class="eyebrow">${esc(finance.departmentName)}</div><h2>${esc(finance.departmentName==='TI'?'Tecnologia':finance.departmentName)}</h2></div><button class="secondary" onclick="goBudget('${esc(finance.departmentName)}')">Abrir orçamento</button></div><div class="row"><span>Orçamento aprovado</span><b>${financeDisplay(finance.budget)}</b></div><div class="row"><span>Planejado</span><b>${financeDisplay(finance.planned)}</b></div><div class="row"><span>Comprometido</span><b>${financeDisplay(finance.committed)}</b></div><div class="row"><span>Realizado</span><b>${financeDisplay(finance.actual)}</b></div><div class="row"><span>Saldo</span><b>${financeDisplay(finance.balance)}</b></div><div class="row"><span>Forecast</span><b>${financeDisplay(finance.forecast)}</b></div><div class="row"><span>Execução</span><b>${percentageDisplay(finance.executionPercentage)}</b></div>${notifications?`<div class="row departmental-operational"><span>Notificações jurídicas</span><b>${notifications.toLocaleString('pt-BR')}</b></div>`:''}<div class="muted finance-source">Fonte: ${esc(finance.source)}</div></section>`}
function departmentScreen(name){if(name==='Jurídico')return 'juridico';if(name==='TI')return 'ti';return 'executivo'}
function executivePage(){const finance=financeRows(),legal=departmentFinance('Jurídico'),technology=departmentFinance('TI'),processRows=state.legalData.processos?.records||[],activeProcesses=processRows.filter(row=>processStatus(row)!=='Finalizado').length,notifications=state.legalData.notificacoes?.count||0,technologyCommitments=state.dashboard.upcoming.filter(e=>e.department==='TI').length,totalActual=finance.reduce((sum,item)=>sum+(Number.isFinite(item.actual)?item.actual:0),0),totalBudget=finance.reduce((sum,item)=>sum+(Number.isFinite(item.budget)?item.budget:0),0);return shell(`<div class="notice">Visão corporativa com indicadores e finanças separados por departamento.</div><div class="grid executive-top"><button class="card executive-action" onclick="go('juridico')"><div class="eyebrow">Jurídico</div><div class="muted">Processos ativos</div><div class="kpi">${activeProcesses.toLocaleString('pt-BR')}</div><span class="pill green">Monday · dado real</span></button><button class="card executive-action" onclick="go('agenda')"><div class="eyebrow">Tecnologia</div><div class="muted">Compromissos agendados</div><div class="kpi">${technologyCommitments.toLocaleString('pt-BR')}</div><span class="pill">Agenda corporativa</span></button><button class="card executive-action" onclick="goBudget('Jurídico')"><div class="eyebrow">Jurídico</div><div class="muted">Realizado</div><div class="kpi">${financeDisplay(legal?.actual)}</div><span class="pill green">${percentageDisplay(legal?.executionPercentage)} do orçamento</span></button><button class="card executive-action" onclick="goBudget('TI')"><div class="eyebrow">Tecnologia</div><div class="muted">Realizado</div><div class="kpi">${financeDisplay(technology?.actual)}</div><span class="pill green">${percentageDisplay(technology?.executionPercentage)} do orçamento</span></button></div><div class="section-title section"><div><div class="eyebrow">Gestão financeira</div><h2>Execução orçamentária por departamento</h2></div><span class="pill">${finance.length} departamentos</span></div><div class="two">${finance.map(item=>executiveFinanceBlock(item,item.departmentName==='Jurídico'?notifications:0)).join('')}</div><button class="card section consolidated-card" onclick="goBudget('Todos')"><div class="section-title"><div><div class="eyebrow">Consolidado COEVO</div><h2>Realizado consolidado</h2></div><div class="kpi">${money(totalActual)}</div></div><div class="consolidated-composition">${finance.map(item=>`<div><span>${esc(item.departmentName==='TI'?'Tecnologia':item.departmentName)}</span><b>${financeDisplay(item.actual)}</b></div>`).join('')}<div class="total"><span>Total</span><b>${money(totalActual)}</b></div></div><div class="muted">Orçamento consolidado: ${money(totalBudget)} · composição exibida por departamento · abrir comparativo →</div></button><div class="two section"><section class="card"><div class="section-title"><h2>Departamentos</h2><span class="pill">${finance.length}</span></div>${finance.map(item=>`<button class="row department-row" onclick="go('${departmentScreen(item.departmentName)}')"><div><b>${esc(item.departmentName==='TI'?'Tecnologia':item.departmentName)}</b><div class="muted">Realizado: ${financeDisplay(item.actual)} · Orçamento: ${financeDisplay(item.budget)} · Execução: ${percentageDisplay(item.executionPercentage)}</div></div><span class="pill">Abrir área</span></button>`).join('')}</section><section class="card"><div class="section-title"><h2>Decisões e compromissos</h2><span class="pill">${state.dashboard.upcoming.length}</span></div>${state.dashboard.upcoming.map(e=>`<div class="row"><div><b>${esc(e.title)}</b><div class="muted">${esc(e.department)} · ${esc(e.date)}</div></div><span class="pill ${e.priority==='Alta'?'red':''}">${esc(e.priority)}</span></div>`).join('')}</section></div>`)}
function alertsPage(){const events=state.dashboard.upcoming;return shell(`<div class="notice">Alertas não são resolvidos silenciosamente. Cada item deve manter responsável, origem e histórico.</div><div class="grid"><div class="card"><div class="muted">Prazos e compromissos</div><div class="kpi">${events.length}</div><span class="pill red">Requer acompanhamento</span></div><div class="card"><div class="muted">Inconsistências de integração</div><div class="kpi">0</div><span class="pill green">Nenhuma registrada</span></div><div class="card"><div class="muted">Decisões pendentes</div><div class="kpi">0</div><span class="pill">Aguardando registros</span></div></div><section class="card section"><div class="section-title"><h2>Alertas & Pendências</h2></div>${events.map(e=>`<div class="row"><div><b>${esc(e.title)}</b><div class="muted">${esc(e.owner)} · ${esc(e.department)}</div></div><span>${esc(e.date)} <span class="pill ${e.priority==='Alta'?'red':''}">${esc(e.priority)}</span></span></div>`).join('')}</section>`)}
function budgetPage(){const all=financeRows(),rows=state.budgetDepartment==='Todos'?all:all.filter(item=>item.departmentName===state.budgetDepartment),totalBudget=all.reduce((sum,item)=>sum+(item.budget||0),0),totalActual=all.reduce((sum,item)=>sum+(item.actual||0),0);return shell(`<div class="notice">${state.budgetDepartment==='Todos'?'Comparativo financeiro por departamento.':'Orçamento filtrado por '+esc(state.budgetDepartment)+'.'} Nenhum consolidado substitui a composição departamental.</div><section class="card"><div class="section-title"><div><h2>${state.budgetDepartment==='Todos'?'Orçamento por departamento':'Orçamento · '+esc(state.budgetDepartment)}</h2><div class="muted">Modelo normalizado por departmentId.</div></div>${state.budgetDepartment==='Todos'?'<span class="pill">Consolidado COEVO</span>':'<button class="secondary" onclick="goBudget(\'Todos\')">Ver comparativo</button>'}</div><div class="table-wrap"><table><thead><tr><th>Departamento</th><th>Orçamento aprovado</th><th>Planejado</th><th>Comprometido</th><th>Realizado</th><th>Saldo</th><th>Forecast</th><th>Execução</th><th>Origem</th></tr></thead><tbody>${rows.map(item=>`<tr><td><b>${esc(item.departmentName==='TI'?'Tecnologia':item.departmentName)}</b></td><td>${financeDisplay(item.budget)}</td><td>${financeDisplay(item.planned)}</td><td>${financeDisplay(item.committed)}</td><td>${financeDisplay(item.actual)}</td><td>${financeDisplay(item.balance)}</td><td>${financeDisplay(item.forecast)}</td><td>${percentageDisplay(item.executionPercentage)}</td><td>${esc(item.source)}</td></tr>`).join('')}</tbody></table></div>${state.budgetDepartment==='Todos'?`<div class="consolidated-composition section">${all.map(item=>`<div><span>Orçamento ${esc(item.departmentName==='TI'?'Tecnologia':item.departmentName)}</span><b>${financeDisplay(item.budget)}</b></div>`).join('')}<div class="total"><span>Orçamento consolidado COEVO</span><b>${money(totalBudget)}</b></div><div><span>Realizado consolidado COEVO</span><b>${money(totalActual)}</b></div></div>`:''}</section>`)}
function integrationsPage(){const monday=state.mondayStatus?.configured;return shell(`<div class="notice">Integrações preservam a origem dos dados e encaminham divergências à Central de Inconsistências.</div><div class="grid"><div class="card"><h2>Monday.com</h2><p class="muted">Jurídico · sete quadros configurados.</p><span class="pill ${monday?'green':'red'}">${monday?'Conectado':'Não configurado'}</span></div>${['Sienge','Construtor de Vendas / CV','E-mail','Clicksign'].map(name=>`<div class="card"><h2>${name}</h2><p class="muted">Conector preparado para configuração futura.</p><span class="pill">Aguardando credencial</span></div>`).join('')}</div>`)}
function logsPage(){const rows=state.auditLog||[];return shell(`<section class="card"><div class="section-title"><h2>Logs / Auditoria do Sistema</h2><span class="pill">${rows.length} eventos recentes</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Ação</th><th>Módulo</th><th>Responsável</th><th>Motivo</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.at||r.createdAt||'—')}</td><td>${esc(r.action||'—')}</td><td>${esc(r.entityType||r.module||'—')}</td><td>${esc(r.userName||r.responsible||'—')}</td><td>${esc(r.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum evento disponível.</div>'}</section>`)}
function placeholderPage(title,description){return shell(`<div class="notice">Módulo corporativo preparado para receber dados e permissões sem redesenhar a navegação.</div><section class="card"><div class="eyebrow">COEVO Alta Performance</div><h2>${esc(title)}</h2><p class="muted">${esc(description)}</p><div class="grid section"><div><div class="muted">Escopo</div><b>Corporativo e departamental</b></div><div><div class="muted">Governança</div><b>RBAC e auditoria</b></div><div><div class="muted">Status</div><b>Em desenvolvimento</b></div></div></section>`)}
function profilePage(){const user=state.me?.user||{};return shell(`<section class="card"><div class="section-title"><h2>Meu Perfil</h2><span class="pill green">Acesso ativo</span></div><div class="row"><span>Nome</span><b>${esc(user.name)}</b></div><div class="row"><span>E-mail</span><b>${esc(user.email)}</b></div><div class="row"><span>Perfil</span><b>${esc(user.role)}</b></div><div class="row"><span>Departamento</span><b>${esc(user.department||'Corporativo')}</b></div><div class="row"><span>Segundo fator</span><b>${user.mfa?'Ativo':'Não configurado'}</b></div></section>`)}

const DASHBOARD_MONTHS=['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];
function dashboardRows(key){return state.legalData[key]?.records||[]}
function dashboardColumn(row,title,id){const byTitle=row.columnsByTitle||{},columns=row.columns||{};return String(byTitle[title]??columns[id]??'').trim()}
function dashboardEnterprise(row){const c=row.columns||{},byTitle=row.columnsByTitle||{},module=row.module||'';const value=byTitle.EMPREENDIMENTO||byTitle['🏢 Empreendimento Consolidado']||(module==='processos'?(c.texto||c.status__1||row.group):module==='notificacoes'?(c.color_mky02302||row.group):module==='distratos'?(c.color_mm28cam9||row.group):module==='honorarios'?(c.status_1__1||row.group):module==='compraVenda'?(c.status7||row.group):row.group);return String(value||'Não informado').trim()||'Não informado'}
